cat > /tmp/reqflow-bundled-ws-check.mjs <<'SCRIPT'
#!/usr/bin/env node
// Read-only, network-free check of ws helpers in an already-emitted ReqFlow main bundle.
// Usage (from repo root):
//   node /tmp/reqflow-bundled-ws-check.mjs apps/desktop/out/main/index.js
//   node /tmp/reqflow-bundled-ws-check.mjs apps/desktop/release/mac-arm64/ReqFlow.app/Contents/Resources/app.asar
// Options: --repo /absolute/repo/root --entry out/main/index.js
// Only existing bundle/ASAR bytes are read; no application startup or builds occur.
import assert from 'node:assert/strict';
import { isUtf8 } from 'node:buffer';
import { createHash } from 'node:crypto';
import { readFileSync, statSync } from 'node:fs';
import { createRequire } from 'node:module';
import { join, resolve } from 'node:path';
import { runInNewContext } from 'node:vm';

let repo = process.cwd();
let entry = 'out/main/index.js';
const inputs = [];
const args = process.argv.slice(2);
for (let i = 0; i < args.length; i++) {
  const arg = args[i];
  if (arg === '--repo' || arg === '--entry') {
    assert(args[i + 1], `${arg} requires a value`);
    if (arg === '--repo') repo = args[++i];
    else entry = args[++i];
  } else {
    assert(!arg.startsWith('--'), `Unknown option: ${arg}`);
    inputs.push(arg);
  }
}
assert(inputs.length, 'Supply an existing main/index.js bundle or app.asar');
repo = resolve(repo);
const installedRequire = createRequire(join(repo, 'package.json'));
const ts = installedRequire('typescript');

function section(source, startMarker, endMarker) {
  const start = source.indexOf(startMarker);
  assert(start >= 0, `Bundle shape changed: missing ${startMarker}`);
  assert.equal(source.indexOf(startMarker, start + startMarker.length), -1,
    `Ambiguous bundle section: ${startMarker}`);
  const end = source.indexOf(endMarker, start + startMarker.length);
  assert(end > start, `Bundle shape changed: missing ${endMarker}`);
  return { text: source.slice(start, end), start };
}

function guardedProbe(source, part, addon, flag, wrapperName) {
  const ast = ts.createSourceFile('emitted-ws.js', part.text,
    ts.ScriptTarget.Latest, true, ts.ScriptKind.JS);
  assert.equal(ast.parseDiagnostics.length, 0, 'Extracted emitted JS must parse');
  const calls = [];
  function visit(node) {
    if (ts.isCallExpression(node) && ts.isIdentifier(node.expression) &&
        node.expression.text === 'require' && node.arguments.length === 1 &&
        ts.isStringLiteral(node.arguments[0]) && node.arguments[0].text === addon) {
      calls.push(node);
    }
    ts.forEachChild(node, visit);
  }
  visit(ast);
  assert.equal(calls.length, 1, `${addon}: expected one literal, guarded require`);
  const call = calls[0];
  let hasCatch = false;
  let hasFlag = false;
  let wrapper;
  for (let p = call.parent; p; p = p.parent) {
    if (ts.isTryStatement(p) && p.catchClause &&
        p.tryBlock.getStart(ast) <= call.getStart(ast) && p.tryBlock.end >= call.end) {
      hasCatch = true;
    }
    if (ts.isIfStatement(p) &&
        p.expression.getText(ast).replace(/\s/g, '') === `!process.env.${flag}` &&
        p.thenStatement.getStart(ast) <= call.getStart(ast) && p.thenStatement.end >= call.end) {
      hasFlag = true;
    }
    if (ts.isFunctionLike(p)) {
      wrapper = p;
      break;
    }
  }
  assert.equal(wrapper?.name?.text, wrapperName, `${addon}: probe must run in its ws loader`);
  assert(hasCatch, `${addon}: require must remain in a try block with a catch`);
  assert(hasFlag, `${addon}: require must retain the ${flag} conditional`);
  const line = source.slice(0, part.start + call.getStart(ast)).split('\n').length;
  console.log(`  guarded require(${JSON.stringify(addon)}): line ${line} PASS`);
}

function frameCheck(helpers, length) {
  const source = Buffer.from(Array.from({ length }, (_, i) => (i * 17 + 23) & 255));
  const original = Buffer.from(source);
  const key = Buffer.from([0x11, 0x22, 0x33, 0x44]);
  const offset = 3;
  const output = Buffer.alloc(length + offset + 3, 0xaa);
  const expected = Buffer.from(output);
  for (let i = 0; i < length; i++) expected[offset + i] = source[i] ^ key[i & 3];
  helpers.mask(source, key, output, offset, length);
  assert(output.equals(expected), `${length}: masking/offset/sentinels incorrect`);
  assert(source.equals(original), `${length}: masking mutated the source`);
  helpers.unmask(output.subarray(offset, offset + length), key);
  expected.set(original, offset);
  assert(output.equals(expected), `${length}: unmasking/odd tail/sentinels incorrect`);
}

function sandboxCheck(code, filename, useNodeUtf8) {
  const probes = [];
  let nativeUtf8Calls = 0;
  const sandbox = {
    Buffer,
    // Deliberately no real process environment, Electron, timers, sockets or fetch.
    process: { env: {} },
    require(id) {
      if (id === 'buffer' || id === 'node:buffer') {
        return useNodeUtf8 ? {
          isUtf8(buffer) {
            nativeUtf8Calls++;
            return isUtf8(buffer);
          },
        } : {};
      }
      assert(['bufferutil', 'utf-8-validate'].includes(id), `Unexpected VM require: ${id}`);
      probes.push(id);
      throw Object.assign(new Error(`Cannot find module '${id}'`), { code: 'MODULE_NOT_FOUND' });
    },
  };
  runInNewContext(code + '\nthis.__wsHelpers = { ...requireBufferUtil(), ...requireValidation() };',
    sandbox, { filename, timeout: 1000 });
  assert.deepEqual(probes, useNodeUtf8 ? ['bufferutil'] : ['bufferutil', 'utf-8-validate'],
    'Addon failure must be caught during actual emitted helper initialization');
  for (const length of [64, 65]) frameCheck(sandbox.__wsHelpers, length);
  assert.equal(sandbox.__wsHelpers.isValidUTF8(Buffer.from('é😀'.repeat(16))), true,
    'Valid 96-byte multibyte UTF-8 rejected');
  for (const length of [64, 65]) {
    assert.equal(sandbox.__wsHelpers.isValidUTF8(Buffer.alloc(length, 0xff)), false,
      `Invalid ${length}-byte UTF-8 accepted`);
  }
  if (useNodeUtf8) assert.equal(nativeUtf8Calls, 3, 'Node buffer.isUtf8 path not exercised');
  console.log(`  ${useNodeUtf8 ? 'Node buffer.isUtf8' : 'pure-JS UTF-8'} path, opt-out flags unset: PASS`);
  console.log(`    caught probes: ${probes.join(', ')}; 64/65-byte offset mask/unmask, source/sentinels, UTF-8: PASS`);
}

function check(input) {
  const path = resolve(repo, input);
  const bytes = path.endsWith('.asar')
    ? installedRequire('@electron/asar').extractFile(path, entry)
    : readFileSync(path);
  const source = bytes.toString('utf8');
  const label = path.endsWith('.asar') ? `${path} -> ${entry}` : path;
  console.log(`CHECK ${label}`);
  console.log(`  artifact mtime: ${statSync(path).mtime.toISOString()}; entry bytes: ${bytes.length}`);
  console.log(`  entry SHA256: ${createHash('sha256').update(bytes).digest('hex')}`);
  assert(!/__viteOptionalPeerDep_(?:bufferutil|utf8Validate)_ws/.test(source),
    'Eager/empty Vite optional-peer stub still exists');
  const buffer = section(source, 'var bufferUtil = { exports: {} };', '\nvar limiter');
  const validation = section(source, 'var validation = { exports: {} };', '\nvar receiver');
  guardedProbe(source, buffer, 'bufferutil', 'WS_NO_BUFFER_UTIL', 'requireBufferUtil');
  guardedProbe(source, validation, 'utf-8-validate', 'WS_NO_UTF_8_VALIDATE', 'requireValidation');
  // Reuse only emitted buffer builtin bindings, not the application imports.
  // Their names can differ between dev and production output.
  const builtinBindings = [...source.matchAll(
    /^(?:const|let|var)\s+[A-Za-z_$][\w$]*\s*=\s*require\(["'](?:node:)?buffer["']\);?$/gm,
  )].map(match => match[0]);
  assert(builtinBindings.length, 'No emitted Node buffer binding found');
  const isolatedCode = [...builtinBindings, buffer.text, validation.text].join('\n');
  sandboxCheck(isolatedCode, `${label} [isolated emitted ws]`, false);
  sandboxCheck(isolatedCode, `${label} [isolated emitted ws]`, true);
  console.log('RESULT PASS\n');
}

for (const input of inputs) {
  try { check(input); }
  catch (error) {
    console.error(`RESULT FAIL: ${input}: ${error.message}`);
    process.exitCode = 1;
  }
}
SCRIPT
node /tmp/reqflow-bundled-ws-check.mjs --repo /Users/jonas/Documents/reqflow apps/desktop/out/main/index.js
